t.script:
(function () {
    const terminalId = "";
    const transactionId = "";
    const wizardId = ;
    const wizardType = "";
    const paymentMethodId = ;
    const isRefund = "" === "True";
    const isDesktopMode = truefalse;
    const isLocalWsServer = truefalse;
    const isMobileConfig = truefalse;
    const localWsUrl = decodeURIComponent("");
    const ONLINE_WS_URL = "wss://bqhdar6mj1.execute-api.eu-central-1.amazonaws.com/prod";

    const waitingWrap = document.getElementById('cloverWaitingWrap');
    const resultWrap = document.getElementById('cloverResultWrap');
    const statusEl = document.getElementById('clover-terminal-status');
    const spinnerEl = document.getElementById('cloverSpinner');
    const resultTitle = document.getElementById('cloverResultTitle');
    const resultMessage = document.getElementById('cloverResultMessage');

    function sleep(ms) {
        return new Promise(function (resolve) { setTimeout(resolve, ms); });
    }

    function isMobileViewport() {
        try {
            if (window.matchMedia && window.matchMedia('(max-width: 576px)').matches) {
                return true;
            }
        } catch (error) {}
        return /Android|iPhone|iPad|iPod|Mobile/i.test(window.navigator.userAgent || '');
    }

    function getAndroidBridge() {
        const contexts = [];
        try {
            if (window.top) {
                contexts.push(window.top);
            }
        } catch (error) {}
        try {
            if (window.parent && window.parent !== window) {
                contexts.push(window.parent);
            }
        } catch (error) {}
        contexts.push(window);
        for (let i = 0; i < contexts.length; i++) {
            const ctx = contexts[i];
            if (!ctx) {
                continue;
            }
            const bridge = ctx.AndroidInterface;
            if (ctx.isNeatPOSAndroidApp && bridge && typeof bridge.onPayment === 'function') {
                return bridge;
            }
        }
        return null;
    }

    async function jsonRpc(route, params) {
        const response = await fetch(route, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: params,
                id: Date.now(),
            }),
        });
        const payload = await response.json();
        return payload.result;
    }

    function expandWizardContainers() {
        try {
            const frame = window.frameElement;
            if (!frame || !window.parent || window.parent === window) {
                return;
            }
            const parentDoc = window.parent.document;
            frame.classList.add('clover-terminal-iframe');
            let el = frame.parentElement;
            while (el) {
                el.style.width = '100%';
                el.style.maxWidth = '100%';
                el.style.boxSizing = 'border-box';
                if (el.classList.contains('modal-body') || el.classList.contains('o_content')) {
                    break;
                }
                el = el.parentElement;
            }
            parentDoc.querySelectorAll('.clover-terminal-processing, .clover-terminal-iframe-wrap').forEach(function (node) {
                node.style.width = '100%';
                node.style.maxWidth = '100%';
            });
        } catch (error) {}
    }

    function applyWizardLayout() {
        try {
            if (!window.parent || window.parent === window) {
                return;
            }
            const parentDoc = window.parent.document;
            const dialog = parentDoc.querySelector('.modal.show .modal-dialog')
                || parentDoc.querySelector('.o_dialog .modal-dialog')
                || parentDoc.querySelector('.modal-dialog');
            if (dialog) {
                dialog.classList.add('clover-terminal-dialog');
            }
            expandWizardContainers();
            const frame = window.frameElement;
            if (!frame) {
                return;
            }
            if (isMobileViewport()) {
                frame.style.minHeight = '280px';
                frame.style.height = 'auto';
            } else {
                frame.style.minHeight = '320px';
                frame.style.height = '360px';
            }
        } catch (error) {}
    }

    function showResult(success, message) {
        waitingWrap.classList.add('hidden');
        resultWrap.classList.add('show');
        resultTitle.textContent = success
            ? (isRefund ? 'Refund successful' : 'Payment successful')
            : (isRefund ? 'Refund declined' : 'Payment declined');
        resultTitle.className = 'result-title ' + (success ? 'ok' : 'err');
        resultMessage.textContent = message || (
            success
                ? (isRefund
                    ? 'The refund was processed successfully. You may close this window.'
                    : 'The payment was processed successfully. You may close this window.')
                : (isRefund
                    ? 'The refund was declined or cancelled. Please try again.'
                    : 'The payment was declined or cancelled. Please try again.')
        );
        expandWizardContainers();
        const frame = window.frameElement;
        if (frame) {
            if (isMobileViewport()) {
                frame.style.minHeight = '220px';
                frame.style.height = 'auto';
            } else {
                frame.style.minHeight = '240px';
                frame.style.height = '280px';
            }
        }
        try {
            if (window.parent && window.parent !== window) {
                window.parent.postMessage({
                    type: 'clover_terminal_result',
                    success: success,
                    wizardId: wizardId,
                    wizardType: wizardType,
                }, '*');
            }
        } catch (error) {}
    }

    function wakeTerminal() {
        const androidBridge = getAndroidBridge();
        if (androidBridge) {
            androidBridge.onPayment("btnCard");
        }
    }

    function isAndroidClient() {
        return (window.navigator.userAgent || '').includes('Android');
    }

    async function notifyDesktopTerminal() {
        if (!isDesktopMode || !terminalId) {
            return;
        }
        let wsUrl = null;
        if (isLocalWsServer && localWsUrl) {
            wsUrl = localWsUrl;
        } else if (!isLocalWsServer) {
            const tokenRes = await jsonRpc('/pos_clover/desktop_ws/token', {
                device_code: terminalId,
                payment_method_id: paymentMethodId,
            });
            if (!tokenRes || tokenRes.status !== 200 || !tokenRes.accessToken) {
                return;
            }
            wsUrl = ONLINE_WS_URL + '?accessToken=' + encodeURIComponent(tokenRes.accessToken);
        }
        if (!wsUrl) {
            return;
        }
        await new Promise(function (resolve) {
            let settled = false;
            const finish = function () {
                if (!settled) {
                    settled = true;
                    resolve();
                }
            };
            try {
                const ws = new WebSocket(wsUrl);
                ws.onopen = function () {
                    try {
                        ws.send(JSON.stringify({ type: 'register', deviceId: terminalId + '-pc' }));
                        ws.send(JSON.stringify({ type: 'message', msgType: 'payment', msgPayload: '' }));
                    } catch (error) {}
                    try { ws.close(); } catch (error) {}
                    finish();
                };
                ws.onerror = function () { finish(); };
                ws.onclose = function () { finish(); };
                setTimeout(finish, 8000);
            } catch (error) {
                finish();
            }
        });
    }

    async function pollPayment() {
        const androidClient = isAndroidClient();
        // Mobile first: Android bridge / deep link, else desktop WS
        if (isMobileConfig && androidClient) {
            wakeTerminal();
            if (!getAndroidBridge()) {
                const redirectUrl = encodeURIComponent(window.location.href);
                window.open('app://neat-clover-payment-android?paymentType=0&redirectUrl=' + redirectUrl);
            }
        } else if (isDesktopMode && !androidClient) {
            await notifyDesktopTerminal();
        }
        applyWizardLayout();
        while (true) {
            try {
                const res = await jsonRpc('/pos_clover/document_payment_status', {
                    terminal_id: terminalId,
                    transaction_id: transactionId,
                    payment_method_id: paymentMethodId,
                });
                if (res && res.status === 200 && res.data) {
                    if (res.data.state === 'done') {
                        showResult(true, res.data.message);
                        return;
                    }
                    if (res.data.state === 'error') {
                        showResult(false, res.data.message);
                        return;
                    }
                    statusEl.textContent = res.data.message;
                    spinnerEl.classList.toggle('hidden', res.data.state !== 'waiting' && res.data.state !== 'processing');
                } else {
                    statusEl.textContent = isRefund
                        ? 'Refund request expired or was not found.'
                        : 'Payment request expired or was not found.';
                    showResult(false, statusEl.textContent);
                    return;
                }
            } catch (error) {
                console.error(error);
            }
            await sleep(2000);
        }
    }

    pollPayment();
})();
